  font-weight: 100;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "Sepehr";
  src: url("./Sepehr-Light.woff2") format("woff2");
  font-weight: 300;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "Sepehr";
  src: url("./Sepehr-Regular.woff2") format("woff2");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "Sepehr";
  src: url("./Sepehr-Medium.woff2") format("woff2");
  font-weight: 500;
  font-style: normal;
  font-display: swap;
}

